import unittest

from solucao import regioes


class TestDicionarioDeListas(unittest.TestCase):
    def test_sul_tem_duas_cidades(self):
        """regioes guarda a lista do sul com duas cidades"""
        self.assertEqual(regioes()["sul"], ["chapeco", "florianopolis"])

    def test_norte_tem_uma_cidade(self):
        """regioes guarda a lista do norte com uma cidade"""
        self.assertEqual(regioes()["norte"], ["manaus"])

    def test_tem_as_duas_regioes(self):
        """regioes guarda as duas regioes"""
        self.assertEqual(sorted(regioes()), ["norte", "sul"])
